% CPU-scope table (spec: motivation_v2_plots.md, §2.4.3 TABLE block).
% Mechanism-level comparison of which training work runs on the Grace CPU:
% SuperOffload's GraceAdam is the fp32 optimizer update loop only.
% 2026-07-26: SwiGLU row REMOVED (toconfirm #1 DISPROVEN, kernel ships
% disabled; used-only rule — its status note lives in §2.4.3 prose).
\begin{table}[t]
  \centering
  \caption{Training work executed on the Grace CPU:
  SuperOffload~\cite{superoffload} versus AsymLoRA.}
  \label{tab:cpu-scope}
  \small
  \begin{tabular}{lcc}
    \toprule
    CPU-executed work & SuperOffload & AsymLoRA \\
    \midrule
    Optimizer update & $\checkmark$ & $\checkmark$ \\
    Gradient ingestion & $\times$ & $\checkmark$ \\
    % continuation line so the column stays narrow enough for one column
    \multicolumn{3}{@{}l@{}}{\quad\footnotesize (bf16$\to$fp32 widen + grad-norm)} \\
    Adapter gradients ($dA$) & $\times$ & $\checkmark$ \\
    \bottomrule
  \end{tabular}
\end{table}

