\usepackage{amssymb}
\newcommand{\motivationplot}[3]{%
  \IfFileExists{#2}{%
    \includegraphics[width=#1]{#2}%
  }{%
    \resizebox{#1}{!}{%
      \fbox{%
        \begin{minipage}[c][0.85in][c]{1.35in}
          \centering
          \footnotesize #3\\[-0.1em]
          \scriptsize \detokenize{#2}
        \end{minipage}%
      }%
    }%
  }%
}

% like \motivationplot but with an explicit placeholder HEIGHT (#2) so a
% missing-file box can match its sibling subfigure's height (fig 7 alignment)
\newcommand{\motivationplotH}[4]{%
  \IfFileExists{#3}{%
    \includegraphics[width=#1]{#3}%
  }{%
    \fbox{%
      \begin{minipage}[b][#2][c]{\dimexpr#1-2\fboxsep-2\fboxrule\relax}
        \centering
        \footnotesize #4\\[-0.1em]
        \scriptsize \detokenize{#3}
      \end{minipage}%
    }%
  }%
}

