cd /tmp/claude-0/-workspace-AsymGEMM-SFT-third-party-AsymGEMM/b3bf7ddd-f2f1-4682-8306-cc64b601d1c6/scratchpad && cat > pdftext2.py <<'EOF'
import zlib, re, sys
raw = open(sys.argv[1],'rb').read()
out=[]
streams = re.findall(rb'stream\r?\n(.*?)endstream', raw, re.S)
for s in streams:
    try: d = zlib.decompress(s)
    except Exception: d = s
    if b'BT' not in d and b'Tj' not in d and b'TJ' not in d: continue
    # literal strings
    for t in re.findall(rb'\(((?:\\.|[^\\()])*)\)\s*T[jJ]', d):
        out.append(('lit', t.decode('latin-1')))
    # hex strings
    for h in re.findall(rb'<([0-9A-Fa-f\s]+)>\s*T[jJ]', d):
        hs = re.sub(rb'\s', b'', h)
        try:
            b = bytes.fromhex(hs.decode())
            # try utf-16 or latin
            if b[:2] in (b'\xfe\xff', b'\xff\xfe'):
                out.append(('hex16', b.decode('utf-16')))
            else:
                # 2-byte glyph ids — print both raw and ascii-guess
                out.append(('hexraw', b.hex()))
        except Exception: pass
    # TJ arrays with hex or literal elements
    for arr in re.findall(rb'\[((?:[^\[\]])*)\]\s*TJ', d):
        parts = re.findall(rb'\(((?:\\.|[^\\()])*)\)|<([0-9A-Fa-f\s]+)>', arr)
        s2=''
        for lit, hx in parts:
            if lit: s2 += lit.decode('latin-1')
            elif hx:
                b = bytes.fromhex(re.sub(rb'\s', b'', hx).decode())
                s2 += '{'+b.hex()+'}'
        if s2: out.append(('arr', s2))
print(f"{len(streams)} streams")
for k,v in out[:200]: print(k, '::', v)
EOF
